const input = $input.first().json;
const message = String(input.message || '').trim();

const patterns = [
  /\b(speak|talk|chat|connect|transfer|handoff|hand off|pass|put)\b[\s\S]{0,50}\b(human|person|agent|representative|support|someone)\b/i,
  /\b(human|real person|person|agent|representative|support person|someone)\b[\s\S]{0,50}\b(speak|talk|chat|connect|transfer|please|now|instead)\b/i,
  /\b(no more|stop)\b[\s\S]{0,20}\b(bot|ai|chatbot)\b/i
];

const explicit_handoff = patterns.some((pattern) => pattern.test(message));

return [{
  json: {
    ...input,
    explicit_handoff
  }
}];

const source = $input.first().json;
const parsed = source.output && typeof source.output === 'object' ? source.output : source;
const explicit = Boolean($('Detect Explicit Human Request').first().json.explicit_handoff);
const needsHuman = Boolean(parsed.needs_human) || explicit;

return [{
  json: {
    session_id: $('Normalize Input').first().json.session_id,
    user_message: $('Normalize Input').first().json.message,
    reply: parsed.reply || (explicit
      ? 'I’ll hand this conversation to the support team and pass along the context from this chat.'
      : 'I could not generate a response.'),
    needs_human: needsHuman,
    escalation_reason: parsed.escalation_reason || (explicit ? 'User explicitly requested a human.' : ''),
    handoff_type: parsed.handoff_type || (explicit ? 'user_requested' : (needsHuman ? 'ai_fallback' : '')),
    handoff_summary: parsed.handoff_summary || (explicit
      ? 'User explicitly requested a human handoff. Review the session conversation for full context.'
      : ''),
    lead_name: parsed.lead_name || '',
    lead_email: parsed.lead_email || '',
    lead_company: parsed.lead_company || '',
    lead_intent: parsed.lead_intent || ''
  }
}];
